#include <bits/stdc++.h>
using namespace std;

string s;

// found[i] == 1 iff pattern occurs in s starting at i (every position for an empty pattern).
vector<char> matches(const string &pattern) {
    size_t n = s.size(), m = pattern.size();
    if (m == 0) return vector<char>(n + 1, 1);
    vector<char> found(n + 1, 0);
    vector<size_t> pi(m, 0);
    for (size_t i = 1, j = 0; i < m; i++) {
        while (j && pattern[i] != pattern[j]) j = pi[j - 1];
        if (pattern[i] == pattern[j]) j++;
        pi[i] = j;
    }
    for (size_t i = 0, j = 0; i < n; i++) {
        while (j && s[i] != pattern[j]) j = pi[j - 1];
        if (s[i] == pattern[j]) j++;
        if (j == m) found[i + 1 - m] = 1, j = pi[j - 1];
    }
    return found;
}

int main() {
    string p;
    getline(cin, s);
    getline(cin, p);
    if (!s.empty() && s.back() == '\r') s.pop_back();
    if (!p.empty() && p.back() == '\r') p.pop_back();
    long long n = s.size(), m = p.size();
    size_t k = p.find('*');
    long long answer = -1;
    if (k == string::npos) {
        vector<char> a = matches(p);
        for (long long i = 0; i <= n; i++)
            if (a[i]) {
                answer = i;
                break;
            }
    } else {
        // Prefix at i, any one character at i+k, suffix at i+k+1.
        vector<char> a = matches(p.substr(0, k)), b = matches(p.substr(k + 1));
        for (long long i = 0; i + m <= n; i++)
            if (a[i] && b[i + k + 1]) {
                answer = i;
                break;
            }
    }
    cout << answer << "\n";
}

