public class Main {
    static String s;

    // found[i] is true iff pattern occurs in s starting at i (every position for an empty pattern).
    static boolean[] matches(String pattern) {
        int n = s.length(), m = pattern.length();
        boolean[] found = new boolean[n + 1];
        if (m == 0) {
            Arrays.fill(found, true);
            return found;
        }
        int[] pi = new int[m];
        for (int i = 1, j = 0; i < m; i++) {
            while (j > 0 && pattern.charAt(i) != pattern.charAt(j)) j = pi[j - 1];
            if (pattern.charAt(i) == pattern.charAt(j)) j++;
            pi[i] = j;
        }
        for (int i = 0, j = 0; i < n; i++) {
            while (j > 0 && s.charAt(i) != pattern.charAt(j)) j = pi[j - 1];
            if (s.charAt(i) == pattern.charAt(j)) j++;
            if (j == m) {
                found[i + 1 - m] = true;
                j = pi[j - 1];
            }
        }
        return found;
    }

