package main

import (
	"bufio"
	"fmt"
	"io"
	"os"
	"strings"
)

var s string

// matches reports, for each start i, whether pattern occurs in s at i
// (every position for an empty pattern).
func matches(pattern string) []bool {
	n, m := len(s), len(pattern)
	found := make([]bool, n+1)
	if m == 0 {
		for i := range found {
			found[i] = true
		}
		return found
	}
	pi := make([]int, m)
	for i, j := 1, 0; i < m; i++ {
		for j > 0 && pattern[i] != pattern[j] {
			j = pi[j-1]
		}
		if pattern[i] == pattern[j] {
			j++
		}
		pi[i] = j
	}
	for i, j := 0, 0; i < n; i++ {
		for j > 0 && s[i] != pattern[j] {
			j = pi[j-1]
		}
		if s[i] == pattern[j] {
			j++
		}
		if j == m {
			found[i+1-m] = true
			j = pi[j-1]
		}
	}
	return found
}

func main() {
	raw, _ := io.ReadAll(bufio.NewReader(os.Stdin))
	lines := strings.Split(string(raw), "\n")
	s = strings.TrimSuffix(lines[0], "\r")
	p := strings.TrimSuffix(lines[1], "\r")
	n, m, k := len(s), len(p), strings.IndexByte(p, '*')
	answer := -1
	if k < 0 {
		a := matches(p)
		for i := 0; i <= n; i++ {
			if a[i] {
				answer = i
				break
			}
		}
	} else {
		// Prefix at i, any one character at i+k, suffix at i+k+1.
		a, b := matches(p[:k]), matches(p[k+1:])
		for i := 0; i+m <= n; i++ {
			if a[i] && b[i+k+1] {
				answer = i
				break
			}
		}
	}
	fmt.Println(answer)
}
